import React from 'react';

const Mobiliz = () => {
  return (
    <div className="min-h-screen bg-gray-100 p-8">
      <h1 className="text-3xl font-bold text-center mb-8">Mobiliz</h1>
      <p className="text-center text-gray-600">Mobiliz sayfası buraya gelecek!</p>
    </div>
  );
};

export default Mobiliz;
